#!/usr/bin/env bash
#
# Build the privileged OpenEUICC APK (plus the unprivileged EasyEUICC APK) from
# the vendored upstream source and package it as a Magisk module.
#
# Requirements: JDK 17, Android SDK with platforms;android-37.0,
# build-tools;37.0.0 and ndk;26.1.10909125, zip, and a signing keystore
# described by openeuicc/keystore.properties (generated by CI, see
# .github/workflows/build.yml).
#
# Environment:
#   OPENEUICC_VERSION_NAME  version name, default "3"
#   OPENEUICC_VERSION_CODE  version code, default 802 + commit count
#   OPENEUICC_KEYSTORE_PROPS  path to keystore.properties (must be absolute or
#                             relative to the repository root)
#   OUTPUT_DIR              output directory, default "out"

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SRC="$ROOT/openeuicc"
OUT="${OUTPUT_DIR:-$ROOT/out}"
MODULE_SRC="$ROOT/magisk-module"

die() { echo "error: $*" >&2; exit 1; }

VERSION_NAME="${OPENEUICC_VERSION_NAME:-3}"
if [ -n "${OPENEUICC_VERSION_CODE:-}" ]; then
    VERSION_CODE="$OPENEUICC_VERSION_CODE"
else
    COMMIT_COUNT="$(git -C "$ROOT" rev-list --count HEAD 2>/dev/null || echo 0)"
    VERSION_CODE=$((802 + COMMIT_COUNT))
fi
# Human readable version shown in module.prop / release titles, and the same
# value with a dot instead of parentheses for file names: GitHub rewrites
# parentheses in release asset file names, so keep them out of file names.
DISPLAY_VERSION="$VERSION_NAME($VERSION_CODE)"
FILE_VERSION="$VERSION_NAME.$VERSION_CODE"

[ -d "$SRC" ] || die "missing vendored upstream source at $SRC"
[ -f "$SRC/keystore.properties" ] || die "missing $SRC/keystore.properties (signing config)"

echo "==> Building OpenEUICC $DISPLAY_VERSION (file version $FILE_VERSION)"
echo "==> JAVA_HOME=${JAVA_HOME:-<unset>}"

(
    cd "$SRC"
    ./gradlew --no-daemon --stacktrace \
        -PopeneuiccVersionName="$VERSION_NAME" \
        -PopeneuiccVersionCode="$VERSION_CODE" \
        :app:assembleRelease \
        :app-unpriv:assembleRelease
)

PRIV_APK="$SRC/app/build/outputs/apk/release/app-release.apk"
UNPRIV_APK="$SRC/app-unpriv/build/outputs/apk/release/app-unpriv-release.apk"
[ -f "$PRIV_APK" ] || die "privileged APK not found at $PRIV_APK"
[ -f "$UNPRIV_APK" ] || die "unprivileged APK not found at $UNPRIV_APK"

echo "==> Packaging Magisk module"
rm -rf "$OUT"
mkdir -p "$OUT"
MODULE_OUT="$OUT/module"

cp -a "$MODULE_SRC/." "$MODULE_OUT/"
rm -f "$MODULE_OUT/system/priv-app/OpenEUICC/.gitkeep"
mkdir -p "$MODULE_OUT/system/priv-app/OpenEUICC" "$MODULE_OUT/system/system_ext/priv-app/OpenEUICC"
install -m 0644 "$PRIV_APK" "$MODULE_OUT/system/priv-app/OpenEUICC/OpenEUICC.apk"
# Second copy: KernelSU setups differ in which partitions they overlay, so ship
# the APK in /system_ext too. The package manager keeps the /system copy and
# ignores the duplicate if both are visible, and falls back to this one when
# /system is not overlaid.
install -m 0644 "$PRIV_APK" "$MODULE_OUT/system/system_ext/priv-app/OpenEUICC/OpenEUICC.apk"
install -m 0644 "$SRC/privapp_whitelist_im.angry.openeuicc.xml" \
    "$MODULE_OUT/system/etc/permissions/privapp_whitelist_im.angry.openeuicc.xml"
install -m 0644 "$SRC/privapp_whitelist_im.angry.openeuicc.xml" \
    "$MODULE_OUT/system/system_ext/etc/permissions/privapp_whitelist_im.angry.openeuicc.xml"
chmod 0755 "$MODULE_OUT/service.sh" "$MODULE_OUT/uninstall.sh" "$MODULE_OUT/post-fs-data.sh"
rm -f "$MODULE_OUT/module.prop.template"

sed -e "s|@VERSION@|$DISPLAY_VERSION|g" \
    -e "s|@VERSION_CODE@|$VERSION_CODE|g" \
    "$MODULE_SRC/module.prop.template" > "$MODULE_OUT/module.prop"

MODULE_ZIP="$OUT/OpenEUICC-Magisk_module-$FILE_VERSION.zip"
(
    cd "$MODULE_OUT"
    zip -q -r -9 "$MODULE_ZIP" .
)
cp "$MODULE_ZIP" "$OUT/OpenEUICC-Magisk_module.zip"

install -m 0644 "$UNPRIV_APK" "$OUT/EasyEUICC-$FILE_VERSION.apk"
printf '%s\n' "$DISPLAY_VERSION" > "$OUT/version.txt"
printf '%s\n' "$FILE_VERSION" > "$OUT/fileversion.txt"

cat > "$OUT/update.json" <<EOF
{
    "version": "$DISPLAY_VERSION",
    "versionCode": $VERSION_CODE,
    "zipUrl": "https://github.com/ban-sky/OpenEUICC_for_Magisk/releases/latest/download/OpenEUICC-Magisk_module.zip",
    "changelog": "https://github.com/ban-sky/OpenEUICC_for_Magisk/releases"
}
EOF

echo "==> Output"
ls -l "$OUT"
echo
echo "==> Module contents"
( cd "$MODULE_OUT" && find . -type f | sort )

echo
echo "==> module.prop"
cat "$MODULE_OUT/module.prop"

echo
echo "Built $DISPLAY_VERSION successfully."
